struct Acc {
    total: u32,
}

impl Acc {
    fn new() -> Self {
        Self { total: 0 }
    }
    fn add(&mut self, n: u32) {
        self.total += n;
    }
    fn doubled(&self) -> u32 {
        self.total * 2
    }
}

fn main() {
    let mut a = Acc::new();
    a.add(3);
    a.add(4);
    println!("{} {}", a.total, a.doubled());
}
